style.css:
@-moz-document domain("youtube.com") {
:root {
    color-scheme: dark;

    --sc-black: #100b0e;
    --sc-black-soft: #171014;
    --sc-brown: #392019;
    --sc-brown-light: #593027;
    --sc-pink: #f3a6c8;
    --sc-pink-light: #ffd7e7;
    --sc-red: #e52c4d;
    --sc-red-dark: #941d35;
    --sc-chrome: #e9e2e8;
    --sc-muted: #bba8b3;
    --sc-border: rgba(243, 166, 200, .15);
    --sc-glass: rgba(34, 20, 28, .88);
    --sc-radius: 18px;
  }

  /* =========================
     GLOBAL ATMOSPHERE
     ========================= */

  html,
  body,
  ytd-app {
    background: var(--sc-black) !important;
    color: var(--sc-chrome) !important;
  }

  body {
    background-image:
      radial-gradient(
        ellipse at 10% 0%,
        rgba(112, 49, 63, .14),
        transparent 42%
      ),
      radial-gradient(
        ellipse at 95% 30%,
        rgba(243, 166, 200, .055),
        transparent 35%
      ) !important;
    background-attachment: fixed !important;
  }

  /* =========================
     TOP BAR
     ========================= */

  ytd-masthead,
  #masthead-container,
  tp-yt-app-header {
    background: rgba(16, 11, 14, .96) !important;
  }

  #masthead-container {
    border-bottom: 1px solid var(--sc-border) !important;
  }

  /* =========================
     SIDEBAR
     ========================= */

  #guide-content,
  ytd-guide-renderer,
  ytd-mini-guide-renderer {
    background: var(--sc-black) !important;
  }

  ytd-guide-entry-renderer,
  ytd-mini-guide-entry-renderer {
    border-radius: 13px !important;
    margin-bottom: 3px !important;
    transition:
      background .2s ease,
      color .2s ease !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background: var(--sc-brown) !important;
  }

  ytd-guide-entry-renderer[active] {
    background: rgba(229, 44, 77, .13) !important;
  }

  ytd-guide-entry-renderer[active] yt-icon {
    color: var(--sc-pink) !important;
  }

  /* =========================
     SEARCH
     ========================= */

  ytd-searchbox {
    border-radius: 28px !important;
  }

  ytd-searchbox #container,
  #container.ytd-searchbox {
    background: var(--sc-black-soft) !important;
    border: 1px solid rgba(243, 166, 200, .2) !important;
    border-radius: 28px !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,.025);
    transition:
      border-color .2s ease,
      box-shadow .2s ease !important;
  }

  ytd-searchbox:focus-within #container {
    border-color: var(--sc-pink) !important;
    box-shadow: 0 0 0 3px rgba(243,166,200,.08) !important;
  }

  #search-icon-legacy {
    background: var(--sc-brown) !important;
    border-color: var(--sc-border) !important;
    color: var(--sc-pink-light) !important;
  }

  #search-icon-legacy:hover {
    background: var(--sc-red-dark) !important;
  }

  /* =========================
     CATEGORY CHIPS
     ========================= */

  #chips-wrapper,
  ytd-feed-filter-chip-bar-renderer {
    background: var(--sc-black) !important;
  }

  yt-chip-cloud-chip-renderer {
    border-radius: 10px !important;
    transition:
      transform .18s ease,
      background .18s ease !important;
  }

  yt-chip-cloud-chip-renderer:hover {
    transform: translateY(-1px);
  }

  yt-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT"] {
    background: #24171d !important;
    color: var(--sc-chrome) !important;
  }

  yt-chip-cloud-chip-renderer[chip-style="STYLE_PRIMARY"] {
    background: var(--sc-pink) !important;
    color: var(--sc-black) !important;
  }

  /* =========================
     VIDEO CARDS
     ========================= */

  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-grid-video-renderer,
  ytd-compact-video-renderer {
    border-radius: var(--sc-radius) !important;
  }

  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-grid-video-renderer {
    transition:
      transform .22s ease,
      filter .22s ease !important;
  }

  ytd-rich-item-renderer:hover,
  ytd-video-renderer:hover,
  ytd-grid-video-renderer:hover {
    transform: translateY(-3px);
  }

  /* =========================
     THUMBNAILS
     ========================= */

  ytd-thumbnail,
  yt-thumbnail-view-model,
  #thumbnail {
    border-radius: var(--sc-radius) !important;
    overflow: hidden !important;
  }

  ytd-thumbnail img,
  yt-thumbnail-view-model img {
    transition: transform .35s ease !important;
  }

  ytd-rich-item-renderer:hover ytd-thumbnail img,
  ytd-video-renderer:hover ytd-thumbnail img {
    transform: scale(1.025);
  }

  /* =========================
     TYPOGRAPHY
     ========================= */

  #video-title,
  #video-title-link,
  yt-formatted-string {
    color: var(--sc-chrome);
  }

  #video-title:hover,
  #video-title-link:hover {
    color: var(--sc-pink-light) !important;
  }

  #metadata-line,
  .inline-metadata-item,
  #channel-name {
    color: var(--sc-muted) !important;
  }

  /* =========================
     BUTTONS
     ========================= */

  yt-button-shape button,
  ytd-button-renderer button,
  ytd-button-renderer a {
    border-radius: 12px !important;
    transition:
      background .18s ease,
      transform .18s ease !important;
  }

  yt-button-shape button:hover,
  ytd-button-renderer button:hover {
    background-color: var(--sc-brown-light) !important;
  }

  /* =========================
     SUBSCRIBE BUTTON
     ========================= */

  ytd-subscribe-button-renderer button,
  yt-subscribe-button-view-model button {
    border-radius: 12px !important;
  }

  /* =========================
     VIDEO PLAYER
     ========================= */

  .html5-video-player {
    border-radius: 18px !important;
    overflow: hidden !important;
  }

  .ytp-chrome-controls .ytp-button:hover,
  .ytp-settings-button:hover {
    color: var(--sc-pink) !important;
  }

  .ytp-play-progress,
  .ytp-swatch-background-color {
    background: var(--sc-red) !important;
  }

  .ytp-volume-slider-handle {
    background: var(--sc-pink) !important;
  }

  .ytp-cued-thumbnail-overlay {
    border-radius: 18px !important;
  }

  /* =========================
     COMMENTS
     ========================= */

  ytd-comment-thread-renderer {
    border-bottom: 1px solid var(--sc-border) !important;
    padding-top: 10px !important;
  }

  #content-text {
    color: var(--sc-chrome) !important;
  }

  /* =========================
     MENUS AND DIALOGS
     ========================= */

  ytd-popup-container,
  ytd-menu-popup-renderer,
  tp-yt-paper-dialog,
  tp-yt-iron-dropdown {
    --yt-spec-menu-background: #21151c;
    --yt-spec-general-background-a: #21151c;
  }

  ytd-menu-popup-renderer {
    border: 1px solid var(--sc-border) !important;
    border-radius: 14px !important;
    overflow: hidden !important;
  }

  /* =========================
     SCROLLBAR
     ========================= */

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-track {
    background: var(--sc-black);
  }

  ::-webkit-scrollbar-thumb {
    background: var(--sc-brown-light);
    border: 2px solid var(--sc-black);
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--sc-red-dark);
  }

  /* =========================
     FOCUS ACCESSIBILITY
     ========================= */

  :focus-visible {
    outline: 2px solid var(--sc-pink) !important;
    outline-offset: 3px !important;
  }

  /* =========================
     REDUCED MOTION
     ========================= */

  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation: none !important;
      transition: none !important;
      scroll-behavior: auto !important;
    }
  }
}
